            "body": "\r\nBEGIN\r\n  -- If custom rrule provided, return it\r\n  IF p_custom_rrule IS NOT NULL AND p_custom_rrule != '' THEN\r\n    RETURN p_custom_rrule;\r\n  END IF;\r\n  \r\n  CASE p_pattern\r\n    WHEN 'daily' THEN\r\n      RETURN 'FREQ=DAILY';\r\n    WHEN 'weekly' THEN\r\n      IF p_days_of_week IS NOT NULL AND array_length(p_days_of_week, 1) > 0 THEN\r\n        -- Convert days to RRULE format (0=Sunday, 1=Monday, etc.)\r\n        RETURN 'FREQ=WEEKLY;BYDAY=' || (\r\n          SELECT string_agg(\r\n            CASE d\r\n              WHEN 0 THEN 'SU'\r\n              WHEN 1 THEN 'MO'\r\n              WHEN 2 THEN 'TU'\r\n              WHEN 3 THEN 'WE'\r\n              WHEN 4 THEN 'TH'\r\n              WHEN 5 THEN 'FR'\r\n              WHEN 6 THEN 'SA'\r\n            END, ','\r\n          )\r\n          FROM unnest(p_days_of_week) AS d\r\n        );\r\n      ELSE\r\n        RETURN 'FREQ=WEEKLY';\r\n      END IF;\r\n    WHEN 'biweekly' THEN\r\n      IF p_days_of_week IS NOT NULL AND array_length(p_days_of_week, 1) > 0 THEN\r\n        -- Convert days to RRULE format with INTERVAL=2\r\n        RETURN 'FREQ=WEEKLY;INTERVAL=2;BYDAY=' || (\r\n          SELECT string_agg(\r\n            CASE d\r\n              WHEN 0 THEN 'SU'\r\n              WHEN 1 THEN 'MO'\r\n              WHEN 2 THEN 'TU'\r\n              WHEN 3 THEN 'WE'\r\n              WHEN 4 THEN 'TH'\r\n              WHEN 5 THEN 'FR'\r\n              WHEN 6 THEN 'SA'\r\n            END, ','\r\n          )\r\n          FROM unnest(p_days_of_week) AS d\r\n        );\r\n      ELSE\r\n        RETURN 'FREQ=WEEKLY;INTERVAL=2';\r\n      END IF;\r\n    WHEN 'monthly' THEN\r\n      RETURN 'FREQ=MONTHLY';\r\n    WHEN 'quarterly' THEN\r\n      RETURN 'FREQ=MONTHLY;INTERVAL=3';\r\n    WHEN 'yearly' THEN\r\n      RETURN 'FREQ=YEARLY';\r\n    ELSE\r\n      RETURN NULL;\r\n  END CASE;\r\nEND;\r\n",
